# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_28_561", r"$(a^{2}+ac+c^{2})-(a^{2}+ab+b^{2})=(c-b)(a+b+c)$ и $(b^{2}+bc+c^{2})-(a^{2}+ac+c^{2})=(b-a)(a+b+c)$; при $b-a=c-b$ разности равны. В ключе обе разности были названы $(b-a)(c-b)$ — это неверное выражение",
  k=r"Разность второго и первого выражений: $(a^{2}+ac+c^{2})-(a^{2}+ab+b^{2})=a(c-b)+(c-b)(c+b)=(c-b)(a+b+c)$; разность третьего и второго: $(b^{2}+bc+c^{2})-(a^{2}+ac+c^{2})=(b-a)(b+a)+c(b-a)=(b-a)(a+b+c)$. Так как $a$, $b$, $c$ — члены арифметической прогрессии, $c-b=b-a$, поэтому разности равны, и три выражения образуют арифметическую прогрессию.")
